class TreeAncestor:
    def __init__(self, n: int, parent: List[int]):
        self.LOG = max(1, n.bit_length())
        self.up = [parent[:]]
        for j in range(1, self.LOG):
            prev = self.up[j - 1]
            self.up.append([prev[p] if p != -1 else -1 for p in prev])

    def getKthAncestor(self, node: int, k: int) -> int:
        j = 0
        while k:
            if k & 1:
                node = self.up[j][node]
                if node == -1:
                    return -1
            k >>= 1
            j += 1
        return node

