class TreeAncestor {
    int LOG;
    vector<vector<int>> up;
public:
    TreeAncestor(int n, vector<int>& parent) {
        LOG = 1;
        while ((1 << LOG) < n) LOG++;
        LOG++;
        up.assign(LOG, vector<int>(n));
        up[0] = parent;
        for (int j = 1; j < LOG; j++)
            for (int v = 0; v < n; v++)
                up[j][v] = up[j-1][v] == -1 ? -1 : up[j-1][up[j-1][v]];
    }

    int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG && node != -1; j++)
            if (k & (1 << j))
                node = up[j][node];
        return node;
    }
};

