class TreeAncestor {
    private int LOG;
    private int[][] up;

    public TreeAncestor(int n, int[] parent) {
        LOG = 1;
        while ((1 << LOG) < n) LOG++;
        LOG++;
        up = new int[LOG][n];
        up[0] = parent.clone();
        for (int j = 1; j < LOG; j++)
            for (int v = 0; v < n; v++)
                up[j][v] = up[j-1][v] == -1 ? -1 : up[j-1][up[j-1][v]];
    }

    public int getKthAncestor(int node, int k) {
        for (int j = 0; j < LOG && node != -1; j++)
            if ((k & (1 << j)) != 0)
                node = up[j][node];
        return node;
    }
}

